// Analytics service for logging page views
// This simulates sending data to an analytics service

export interface PageViewData {
  path: string;
  timestamp: Date;
  userAgent?: string;
}

export async function logPageView(data: PageViewData): Promise<void> {
  // Simulate network latency to an analytics service
  await new Promise((resolve) => setTimeout(resolve, 100));

  // In a real application, this would send data to an analytics service
  // e.g., Google Analytics, Mixpanel, or a custom analytics backend
  console.log('[Analytics] Page view logged:', {
    path: data.path,
    timestamp: data.timestamp.toISOString(),
    userAgent: data.userAgent ?? 'unknown',
  });
}

