import { after } from 'next/server';
import { headers } from 'next/headers';
import { logPageView } from './analytics';

export default async function Home() {
  const headersList = await headers();
  const userAgent = headersList.get('user-agent') ?? undefined;

  // Schedule analytics logging to run after the response is sent
  // This does NOT block the response - the user sees the page immediately
  after(async () => {
    await logPageView({
      path: '/',
      timestamp: new Date(),
      userAgent,
    });
  });

  return (
    <main>
      <h1>Welcome to Our Site</h1>
      <p>We're glad you're here! Explore and enjoy your visit.</p>
    </main>
  );
}

